// Generate all search queries for films
const queries = [
  { query: 'فيلم تركي مدبلج بالعربية كامل',    origin: 'turkish',  language: 'ar_dubbed' },
  { query: 'فيلم هندي مدبلج بالعربية كامل',    origin: 'indian',   language: 'ar_dubbed' },
  { query: 'فيلم كوري مدبلج بالعربية كامل',    origin: 'korean',   language: 'ar_dubbed' },
  { query: 'فيلم أمريكي مدبلج بالعربية كامل',  origin: 'american', language: 'ar_dubbed' },
  { query: 'فيلم مغربي بالدارجة كامل',          origin: 'moroccan', language: 'darija'    },
  { query: 'فيلم مدبلج بالدارجة المغربية كامل', origin: 'other',    language: 'darija'    },
  { query: 'فيلم تركي مدبلج 2024 كامل',         origin: 'turkish',  language: 'ar_dubbed' },
  { query: 'فيلم هندي بوليوود مدبلج عربي',      origin: 'indian',   language: 'ar_dubbed' }
];
console.log(`Generated ${queries.length} search queries`);
return queries.map(q => ({ json: q }));

// Enrich each result with origin/language from the query context
const results = $input.first().json.results || [];
const query = $('Generate Queries').item.json;
console.log(`Query: ${query.query} → ${results.length} results`);
const enriched = results
  .filter(r => r.embeddable !== false)
  .filter(r => !r.duration_sec || r.duration_sec > 3600) // films > 60min
  .map(r => ({
    ...r,
    origin:   r.origin   !== 'other' ? r.origin   : query.origin,
    language: r.language !== 'ar_dubbed' ? r.language : query.language,
    query:    query.query
  }));
console.log(`After filter: ${enriched.length} valid films`);
return [{ json: { items: enriched, query: query.query } }];

const items = $input.all();
let totalImported=0, totalSkipped=0, totalErrors=0;
for (const item of items) {
  totalImported += item.json.imported || 0;
  totalSkipped  += item.json.skipped  || 0;
  totalErrors   += item.json.errors   || 0;
}
console.log(`✅ Films auto-discovery done: ${totalImported} imported, ${totalSkipped} skipped, ${totalErrors} errors`);
return [{ json: { done: true, imported: totalImported, skipped: totalSkipped, errors: totalErrors, run_at: new Date().toISOString() } }];
